require('dotenv').config();
const express = require('express');
const mongoose = require('mongoose');
const session = require('express-session');
const MongoStore = require('connect-mongo');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const bcrypt = require('bcryptjs');
const crypto = require('crypto');
const nodemailer = require('nodemailer');
const path = require('path');
const fs = require('fs');
const portal = require('./portal');

const app = express();
const port = Number(process.env.PORT || 3000);
const prod = process.env.NODE_ENV === 'production';
const mongoUri = process.env.MONGODB_URI || process.env.MONGO_URI || (!prod ? 'mongodb://127.0.0.1:27017/xwadda_ke_production' : '');
const mongoDbName = process.env.MONGODB_DB || 'xwadda_ke_production';
if (prod && (!process.env.SESSION_SECRET || process.env.SESSION_SECRET.length < 32)) throw new Error('Set a 32-character SESSION_SECRET');
if (prod && !mongoUri) throw new Error('Set MONGO_URI to the MongoDB connection string from Coolify');
app.set('trust proxy', 1);
app.disable('x-powered-by');
app.use(helmet({ contentSecurityPolicy: false }));
app.use(express.urlencoded({ extended: false, limit: '30kb' }));
app.use(express.json({ limit: '30kb', verify: (req,res,buf)=>{ req.rawBody=Buffer.from(buf); } }));

const User = mongoose.model('User', new mongoose.Schema({
  name: { type: String, required: true, trim: true, maxlength: 120 },
  email: { type: String, required: true, unique: true, lowercase: true, trim: true, index: true },
  passwordHash: { type: String, required: true }, role: { type: String, enum: ['user','admin'], default: 'user' },
  status: { type: String, enum: ['active','suspended','closed'], default: 'active' }, verifiedAt: Date,
  verifyHash: String, verifyExpires: Date, createdAt: { type: Date, default: Date.now }
}));
const Deal = mongoose.model('Deal', new mongoose.Schema({
  publicId: { type: String, required: true, unique: true }, code: { type: String, unique: true, sparse: true, uppercase: true, minlength: 5, maxlength: 5 },
  creatorId: { type: mongoose.Schema.Types.ObjectId, ref: 'User' }, buyerId: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  sellerId: { type: mongoose.Schema.Types.ObjectId, ref: 'User' }, thirdPartyId: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  buyerName: String, sellerName: String, thirdPartyName: String, buyerNameKey: String, sellerNameKey: String, thirdPartyNameKey: String, sellerEmail: String,
  title: { type: String, required: true, maxlength: 160 }, terms: { type: String, required: true, maxlength: 10000 },
  currency: { type: String, enum: ['KES','USDT'], required: true }, amountMinor: { type: Number, required: true }, feeMinor: { type: Number, required: true },
  status: { type: String, enum: ['open','awaiting_seller','draft','accepted','awaiting_payment','payment_review','funded','delivered','release_requested','completed','disputed','cancelled','refunded'], default: 'open' },
  inviteHash: String, inviteExpires: Date, paymentRef: String, paymentMethod: String, cryptoNetwork: String, txHash: String,
  createdAt: { type: Date, default: Date.now }, updatedAt: { type: Date, default: Date.now }
}, { minimize: false }));
const SafetyReport = mongoose.model('SafetyReport', new mongoose.Schema({
  reporterId: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true }, category: String, details: { type: String, maxlength: 8000 },
  status: { type: String, enum: ['pending','reviewed','dismissed'], default: 'pending' }, createdAt: { type: Date, default: Date.now }
}));
const Audit = mongoose.model('Audit', new mongoose.Schema({ adminId: mongoose.Schema.Types.ObjectId, dealId: mongoose.Schema.Types.ObjectId, action: String, details: Object, createdAt: { type: Date, default: Date.now } }));
const RoomMessage = mongoose.model('RoomMessage', new mongoose.Schema({ dealId: { type: mongoose.Schema.Types.ObjectId, ref: 'Deal', required: true, index: true }, userId: mongoose.Schema.Types.ObjectId, name: String, role: String, kind: { type: String, enum: ['message','event'], default: 'message' }, body: { type: String, required: true, maxlength: 2000 }, createdAt: { type: Date, default: Date.now } }));
const PaymentIntent = mongoose.model('PaymentIntent', new mongoose.Schema({ dealId: { type: mongoose.Schema.Types.ObjectId, ref: 'Deal', required: true }, provider: { type: String, enum: ['hashpay','crypto'], required: true }, providerReference: { type: String, required: true, unique: true }, network: String, amountMinor: { type: Number, required: true }, currency: { type: String, enum: ['KES','USDT'], required: true }, status: { type: String, enum: ['pending','confirmed','failed','exception'], default: 'pending' }, providerTransactionId: String, providerPayload: Object, createdAt: { type: Date, default: Date.now } }));

app.use(session({ name: 'xwadda.ke.sid', secret: process.env.SESSION_SECRET || 'development-only-change-this-secret-32', resave: false, saveUninitialized: false,
  store: MongoStore.create({ mongoUrl: mongoUri, dbName: mongoDbName, collectionName: 'xwadda_sessions', ttl: 60 * 60 * 24 * 7 }),
  cookie: { httpOnly: true, sameSite: 'lax', secure: process.env.COOKIE_SECURE === 'true' ? true : process.env.COOKIE_SECURE === 'false' ? false : 'auto', maxAge: 7 * 24 * 60 * 60 * 1000 }
}));
const authLimiter = rateLimit({ windowMs: 15 * 60 * 1000, limit: 12, standardHeaders: 'draft-7', legacyHeaders: false });
const roomJoinLimiter = rateLimit({ windowMs: 15 * 60 * 1000, limit: 10, standardHeaders: 'draft-7', legacyHeaders: false });

function feeMinor(currency, principal) {
  if (!Number.isSafeInteger(principal) || principal < 1) throw new Error('Invalid amount');
  if (currency === 'KES') return Math.round((Math.min(principal,1000000)*.03 + Math.max(0,Math.min(principal-1000000,9000000))*.02 + Math.max(0,principal-10000000)*.01)/100)*100;
  if (currency === 'USDT') return Math.round(Math.min(principal,10000)*.025 + Math.max(0,Math.min(principal-10000,90000))*.015 + Math.max(0,principal-100000)*.01);
  throw new Error('Unsupported currency');
}
function csrf(req,res,next) {
  // A stateless signed token avoids false 419s when a reverse proxy or scheme
  // change causes the browser to omit the Mongo session cookie on a fresh form.
  const issued = `${Date.now()}.${crypto.randomBytes(18).toString('hex')}`;
  const signature = crypto.createHmac('sha256', process.env.SESSION_SECRET || 'development-only-change-this-secret-32').update(issued).digest('hex');
  res.locals.csrf = `${issued}.${signature}`; next();
}
function checkCsrf(req,res,next) {
  const token = String(req.body && req.body.csrf || '');
  const parts = token.split('.');
  if (parts.length !== 3 || !/^\d{13}$/.test(parts[0]) || !/^[a-f0-9]{36}$/.test(parts[1]) || !/^[a-f0-9]{64}$/.test(parts[2])) return res.status(419).send('This form has expired. Refresh the page and try again.');
  const issuedAt = Number(parts[0]);
  if (!Number.isSafeInteger(issuedAt) || issuedAt > Date.now() + 60_000 || Date.now() - issuedAt > 4 * 60 * 60 * 1000) return res.status(419).send('This form has expired. Refresh the page and try again.');
  const expected = crypto.createHmac('sha256', process.env.SESSION_SECRET || 'development-only-change-this-secret-32').update(`${parts[0]}.${parts[1]}`).digest();
  const supplied = Buffer.from(parts[2], 'hex');
  if (supplied.length !== expected.length || !crypto.timingSafeEqual(supplied, expected)) return res.status(419).send('This form has expired. Refresh the page and try again.');
  next();
}
function signedIn(req,res,next) { if (!req.session.user) return res.redirect('/account'); next(); }
function adminOnly(req,res,next) { if (!req.session.user || req.session.user.role !== 'admin') return res.status(403).send('Administrator access required.'); next(); }
function escapeHtml(s='') { return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function render(title, body, req) {
  const user = req.session.user;
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#111"><title>${escapeHtml(title)} · XWADDA.KE</title><link rel="stylesheet" href="/assets/portal.css"><style>body{background:#f5f5f5;color:#151515}.simple-page{max-width:850px;margin:48px auto;padding:28px;background:#fff;border:1px solid #ddd;border-radius:14px}.simple-page h1,.simple-page h2{color:#111}.simple-page label{display:block;margin:12px 0;font-size:14px}.simple-page input,.simple-page textarea,.simple-page select{display:block;width:100%;padding:12px;border:1px solid #bbb;border-radius:6px;margin-top:5px}.simple-page .row{display:flex;gap:14px}.simple-page .row>*{flex:1}.notice{padding:12px;background:#f0f0f0;border-left:3px solid #111;margin:12px 0}.list{border-top:1px solid #ddd;padding:14px 0}.site-copyright{text-align:center;padding:26px;color:#555}</style><link rel="stylesheet" href="/assets/preferences.css"></head><body><header class="site-header"><a class="site-brand" href="/"><img src="/assets/xw-logo.png" alt=""><span>XWADDA<small>.KE</small></span></a><nav><a href="/my-deals">My deals</a> · ${user?`<span>${escapeHtml(user.name)}</span> · <form method="post" action="/logout" style="display:inline"><input type="hidden" name="csrf" value="${escapeHtml(res.locals.csrf)}"><button type="submit">Sign out</button></form>`:'<a href="/signin">Sign in</a> · <a href="/signup">Create account</a> · <a href="/contact">Support</a>'} ${user&&user.role==='admin'?'· <a href="/admin">Admin</a>':''}</nav><div class="site-controls"><button type="button" data-theme-toggle>Dark mode</button><select data-language aria-label="Language"><option value="en">English</option><option value="fil">Filipino</option><option value="ar">العربية</option></select></div></header><div class="page-body">${body}</div><footer class="site-copyright">© ${new Date().getUTCFullYear()} XWADDA.KE. All rights reserved. · <a href="/contact">Contact support</a></footer><script defer src="/assets/preferences.js"></script></body></html>`;
}
function amountFromForm(value,currency) { if (!/^\d{1,9}(\.\d{1,2})?$/.test(value)) throw new Error('Enter a valid amount.'); if(currency==='KES'&&value.includes('.')) throw new Error('KES amounts must be whole shillings.'); const n=Math.round(Number(value)*100); if(!Number.isSafeInteger(n)||n<1||n>100000000000) throw new Error('Amount is outside the allowed range.'); return n; }
function money(currency,minor) { return `${currency} ${(minor/100).toLocaleString('en-KE',{minimumFractionDigits:currency==='KES'?0:2,maximumFractionDigits:2})}`; }
function mailer() { if (!process.env.MAIL_HOST) return null; return nodemailer.createTransport({host:process.env.MAIL_HOST,port:Number(process.env.MAIL_PORT||587),secure:Number(process.env.MAIL_PORT)===465,auth:{user:process.env.MAIL_USER,pass:process.env.MAIL_PASSWORD}}); }
async function sendMail(to,subject,text) { const t=mailer(); if(!t) throw new Error('Email is not configured. Add SMTP settings before registration.'); return t.sendMail({from:process.env.MAIL_FROM,to,subject,text}); }
function googleSignInMarkup(csrfToken) {
  const clientId = String(process.env.GOOGLE_CLIENT_ID || '').trim();
  if (!clientId) return '';
  return `<div class="auth-divider"><span>OR</span></div><form id="google-auth-form" method="post" action="/auth/google"><input type="hidden" name="csrf" value="${escapeHtml(csrfToken)}"><input id="google-id-token" type="hidden" name="credential"><div id="google-signin-button"></div></form><script>function handleGoogleCredential(response){document.getElementById('google-id-token').value=response.credential;document.getElementById('google-auth-form').requestSubmit()}</script><script src="https://accounts.google.com/gsi/client" async defer onload="google.accounts.id.initialize({client_id:${JSON.stringify(clientId)},callback:handleGoogleCredential});google.accounts.id.renderButton(document.getElementById('google-signin-button'),{theme:'outline',size:'large',shape:'rectangular',text:'continue_with',width:Math.min(document.getElementById('google-signin-button').clientWidth||320,400)})"></script>`;
}
let googleCertCache = { certs: null, expiresAt: 0 };
async function verifyGoogleCredential(token) {
  const pieces = String(token || '').split('.');
  if (pieces.length !== 3) throw new Error('Google sign-in could not be verified. Please try again.');
  let header, claims;
  try { header = JSON.parse(Buffer.from(pieces[0], 'base64url').toString()); claims = JSON.parse(Buffer.from(pieces[1], 'base64url').toString()); }
  catch { throw new Error('Google sign-in could not be verified. Please try again.'); }
  if (header.alg !== 'RS256' || !header.kid || !process.env.GOOGLE_CLIENT_ID) throw new Error('Google sign-in is not configured correctly.');
  if (!googleCertCache.certs || googleCertCache.expiresAt < Date.now()) {
    const response = await fetch('https://www.googleapis.com/oauth2/v1/certs');
    if (!response.ok) throw new Error('Google sign-in is temporarily unavailable.');
    const certs = await response.json();
    const cacheControl = response.headers.get('cache-control') || '';
    const maxAge = Number((cacheControl.match(/max-age=(\d+)/i) || [])[1] || 3600);
    googleCertCache = { certs, expiresAt: Date.now() + Math.min(maxAge, 3600) * 1000 };
  }
  const cert = googleCertCache.certs[header.kid];
  if (!cert || !crypto.verify('RSA-SHA256', Buffer.from(`${pieces[0]}.${pieces[1]}`), cert, Buffer.from(pieces[2], 'base64url'))) throw new Error('Google sign-in could not be verified. Please try again.');
  const now = Math.floor(Date.now() / 1000);
  if (!['accounts.google.com', 'https://accounts.google.com'].includes(claims.iss) || claims.aud !== process.env.GOOGLE_CLIENT_ID || !claims.sub || !claims.email || claims.email_verified !== true || !Number.isFinite(claims.exp) || claims.exp <= now || (claims.iat && claims.iat > now + 60)) throw new Error('Google did not provide a verified account.');
  return { email: String(claims.email).toLowerCase(), name: String(claims.name || claims.given_name || claims.email).trim().slice(0, 120) };
}

const ROLE_FIELDS = { buyer: ['buyerId','buyerName','buyerNameKey'], seller: ['sellerId','sellerName','sellerNameKey'], third_party: ['thirdPartyId','thirdPartyName','thirdPartyNameKey'] };
function roomRole(deal,userId) { for (const role of Object.keys(ROLE_FIELDS)) if (String(deal[ROLE_FIELDS[role][0]]||'')===String(userId)) return role; return null; }
function makeRoomCode() { const alphabet='ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; return Array.from({length:5},()=>alphabet[crypto.randomInt(alphabet.length)]).join(''); }
function roomStatusLabel(status) { return ({open:'Waiting for participants',awaiting_seller:'Waiting for seller',draft:'Draft',accepted:'Terms accepted',awaiting_payment:'Ready for deposit',payment_review:'Deposit under review',funded:'Funds confirmed',delivered:'Delivery submitted',disputed:'Dispute under review',release_requested:'Payout requested',completed:'Released',cancelled:'Cancelled',refunded:'Refund recorded'})[status]||status.replaceAll('_',' '); }
function roleName(role) { return role==='third_party'?'Third party':role?role[0].toUpperCase()+role.slice(1):'Participant'; }
async function addRoomEvent(deal,user,role,body) { await RoomMessage.create({dealId:deal._id,userId:user?user.id:undefined,name:user?user.name:'XWADDA system',role:role||'system',kind:'event',body}); }
async function accountDeals(user) { return Deal.find({$or:[{buyerId:user.id},{sellerId:user.id},{thirdPartyId:user.id}]}).sort({updatedAt:-1,createdAt:-1}).limit(100).lean(); }

app.use(csrf);
app.get('/contact',(req,res)=>{const email=String(process.env.SUPPORT_EMAIL||'').trim();const content='<section class="auth-card"><span class="eyebrow">XWADDA SUPPORT</span><h1>How can we help?</h1><p>For a question about a room or payment, include the five-character room code and the email on your account. Do not send passwords or private keys.</p>'+(email?'<p><a class="button primary" href="mailto:'+escapeHtml(email)+'">Email support</a></p>':'<p>Support email is being set up. Please check back soon.</p>')+'<p><a href="/">← Back to XWADDA</a></p></section>';res.send(render('Contact support',content,req));});
app.get('/health', (req,res)=>res.json({ok:true, service:'xwadda'}));
app.get('/', async(req,res)=>{if(!req.session.user){const html=fs.readFileSync(path.join(__dirname,'public','landing.html'),'utf8');return res.type('html').send(html);}const deals=await accountDeals(req.session.user);return res.send(render('Your dashboard',portal.dashboard(req.session.user,deals,res.locals.csrf,{escapeHtml,money,statusLabel:roomStatusLabel}),req));});
app.get('/signin',(req,res)=>{
  const notice=req.query.message?'<div class="notice">'+escapeHtml(req.query.message)+'</div>':'';
  const content=notice+'<section class="auth-card"><span class="eyebrow">WELCOME BACK</span><h1>Sign in to XWADDA</h1><p>Your account and deal history are private to you.</p><form method="post" action="/auth/login" class="auth-form"><input type="hidden" name="csrf" value="'+escapeHtml(res.locals.csrf)+'"><label>Email<input type="email" name="email" autocomplete="email" required></label><label>Password<input type="password" name="password" autocomplete="current-password" required></label><button class="button primary full">Sign in</button></form>'+googleSignInMarkup(res.locals.csrf)+'<p class="auth-switch">New to XWADDA? <a href="/signup">Create an account</a></p></section>';
  res.send(render('Sign in',content,req));
});
app.get('/signup',(req,res)=>{
  const notice=req.query.message?'<div class="notice">'+escapeHtml(req.query.message)+'</div>':'';
  const content=notice+'<section class="auth-card"><span class="eyebrow">GET STARTED</span><h1>Create your account</h1><p>One account to create shared rooms and join deals.</p><form method="post" action="/auth/register" class="auth-form"><input type="hidden" name="csrf" value="'+escapeHtml(res.locals.csrf)+'"><label>Your name<input name="name" autocomplete="name" required minlength="2" maxlength="120"></label><label>Email<input type="email" name="email" autocomplete="email" required></label><label>Password<input type="password" name="password" autocomplete="new-password" minlength="6" required><small>At least 6 characters.</small></label><button class="button primary full">Create account</button></form>'+googleSignInMarkup(res.locals.csrf)+'<p class="auth-switch">Already registered? <a href="/signin">Sign in</a></p></section>';
  res.send(render('Create account',content,req));
});
app.get('/account',(req,res)=>res.redirect('/signin'));
app.post('/auth/google',authLimiter,checkCsrf,async(req,res)=>{
  try {
    const identity=await verifyGoogleCredential(req.body.credential);
    let user=await User.findOne({email:identity.email});
    if(!user) user=await User.create({name:identity.name,email:identity.email,role:identity.email===String(process.env.ADMIN_EMAIL||'').trim().toLowerCase()?'admin':'user',passwordHash:await bcrypt.hash(crypto.randomBytes(32).toString('hex'),12),verifiedAt:new Date()});
    else if(!user.verifiedAt){user.verifiedAt=new Date();await user.save();}
    if(user.status!=='active') return res.redirect('/signin?message='+encodeURIComponent('This account is not currently available.'));
    req.session.regenerate(err=>{if(err)return res.status(500).send('Sign-in failed.');req.session.user={id:String(user._id),name:user.name,email:user.email,role:user.role};req.session.save(saveErr=>saveErr?res.status(500).send('Sign-in failed. Please try again.'):res.redirect('/'));});
  } catch(e) { res.redirect('/signin?message='+encodeURIComponent(e.message||'Google sign-in failed. Please try again.')); }
});
app.post('/auth/register',authLimiter,checkCsrf,async(req,res)=>{
  try {
    const name=String(req.body.name||'').trim(),email=String(req.body.email||'').trim().toLowerCase(),password=String(req.body.password||'');
    if(name.length<2||name.length>120||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||password.length<6) throw new Error('Enter a valid name and email. Password must have at least 6 characters.');
    const verifyByEmail=Boolean(process.env.MAIL_HOST),token=verifyByEmail?crypto.randomBytes(32).toString('hex'):null;
    await User.create({name,email,role:email===String(process.env.ADMIN_EMAIL||'').trim().toLowerCase()?'admin':'user',passwordHash:await bcrypt.hash(password,12),verifiedAt:verifyByEmail?undefined:new Date(),verifyHash:token?crypto.createHash('sha256').update(token).digest('hex'):undefined,verifyExpires:token?new Date(Date.now()+86400000):undefined});
    if(verifyByEmail){const url=(process.env.APP_URL||'http://localhost:3000')+'/verify?token='+token;await sendMail(email,'Verify your XWADDA.KE account','Verify your email within 24 hours: '+url);return res.redirect('/signin?message='+encodeURIComponent('Account created. Check your email for the verification link.'));}
    return res.redirect('/signin?message='+encodeURIComponent('Account created. You can sign in now.'));
  } catch(e) { return res.redirect('/signup?message='+encodeURIComponent(e.code===11000?'That email is already registered.':e.message||'Account creation failed.')); }
});
app.get('/verify',async(req,res)=>{const hash=crypto.createHash('sha256').update(String(req.query.token||'')).digest('hex');const user=await User.findOne({verifyHash:hash,verifyExpires:{$gt:new Date()}});if(!user)return res.status(400).send(render('Verification',`<h1>Verification link expired</h1><p>Please register again or contact support.</p>`,req));user.verifiedAt=new Date();user.verifyHash=undefined;user.verifyExpires=undefined;await user.save();res.redirect('/signin?message='+encodeURIComponent('Email verified. You can now sign in.'));});
app.post('/auth/login',authLimiter,checkCsrf,async(req,res)=>{const email=String(req.body.email||'').trim().toLowerCase();const user=await User.findOne({email});if(!user||!await bcrypt.compare(String(req.body.password||''),user.passwordHash))return res.redirect('/signin?message='+encodeURIComponent('Email or password is incorrect.'));if(!user.verifiedAt)return res.redirect('/signin?message='+encodeURIComponent('Verify your email before signing in.'));if(user.status!=='active')return res.redirect('/signin?message='+encodeURIComponent('This account is not currently available.'));req.session.regenerate(err=>{if(err)return res.status(500).send('Sign-in failed.');req.session.user={id:String(user._id),name:user.name,email:user.email,role:user.role};req.session.save(saveErr=>saveErr?res.status(500).send('Sign-in failed. Please try again.'):res.redirect('/'));});});
app.post('/logout',checkCsrf,(req,res)=>req.session.destroy(()=>res.redirect('/')));
app.get('/my-deals',signedIn,(req,res)=>res.redirect('/'));
app.post('/deals',signedIn,checkCsrf,async(req,res)=>{try{
  const user=req.session.user,title=String(req.body.title||'').trim(),terms=String(req.body.terms||'').trim(),currency=String(req.body.currency||'KES'),role=String(req.body.role||'seller');
  if(title.length<3||title.length>160||terms.length<10||terms.length>10000||!ROLE_FIELDS[role])throw new Error('Enter a title, clear terms and choose a valid role.');
  const amountMinor=amountFromForm(String(req.body.amount||''),currency),fee=feeMinor(currency,amountMinor),[slot,nameField,nameKeyField]=ROLE_FIELDS[role];let created;
  for(let attempt=0;attempt<8&&!created;attempt++){const code=makeRoomCode();try{created=await Deal.create({publicId:crypto.randomBytes(13).toString('hex'),code,creatorId:user.id,[slot]:user.id,[nameField]:user.name,[nameKeyField]:user.name.trim().toLocaleLowerCase(),title,terms,currency,amountMinor,feeMinor:fee,status:'open',createdAt:new Date(),updatedAt:new Date()});}catch(err){if(err.code!==11000)throw err;}}
  if(!created)throw new Error('Could not create a unique room code. Please try again.');await addRoomEvent(created,user,role,`${user.name} created this room as ${roleName(role)}.`);res.redirect(`/deal/${created.code}`);
}catch(e){res.status(422).send(render('Room not created',`<h1>Room not created</h1><div class="notice">${escapeHtml(e.message)}</div><a class="button primary" href="/">Return to dashboard</a>`,req));}});
app.post('/deals/join',signedIn,roomJoinLimiter,checkCsrf,async(req,res)=>{try{
  const user=req.session.user,code=String(req.body.code||'').trim().toUpperCase(),role=String(req.body.role||''),mapping=ROLE_FIELDS[role];if(!/^[A-HJ-NP-Z2-9]{5}$/.test(code)||!mapping)throw new Error('Enter a valid five-character code and choose a role.');
  const deal=await Deal.findOne({code});if(!deal)throw new Error('That room code was not found. Check the code with the person who shared it.');if(['completed','cancelled','refunded'].includes(deal.status))throw new Error('This deal room is closed and no longer accepts participants.');
  const already=roomRole(deal,user.id);if(already)return res.redirect(`/deal/${deal.code}`);
  const occupiedNames=[deal.buyerName,deal.sellerName,deal.thirdPartyName].filter(Boolean).map(n=>n.trim().toLocaleLowerCase());if(occupiedNames.includes(user.name.trim().toLocaleLowerCase()))throw new Error('That participant name is already in this room. Ask the room owner to verify the correct account name.');
  const [slot,nameField,nameKeyField]=mapping;if(deal[slot])throw new Error(`The ${roleName(role).toLowerCase()} seat has already been claimed.`);
  const buyerPresent=Boolean(deal.buyerId)||(role==='buyer'),sellerPresent=Boolean(deal.sellerId)||(role==='seller');const nextStatus=buyerPresent&&sellerPresent?'awaiting_payment':deal.status;
  const nameKey=user.name.trim().toLocaleLowerCase(),guardNames={};for(const other of Object.keys(ROLE_FIELDS)){if(other!==role)guardNames[ROLE_FIELDS[other][2]]={$ne:nameKey};}
  const updated=await Deal.findOneAndUpdate({_id:deal._id,status:{$nin:['completed','cancelled','refunded']},[slot]:{$exists:false},buyerId:{$ne:user.id},sellerId:{$ne:user.id},thirdPartyId:{$ne:user.id},...guardNames},{$set:{[slot]:user.id,[nameField]:user.name,[nameKeyField]:nameKey,status:nextStatus,updatedAt:new Date()}},{new:true});
  if(!updated)throw new Error('That seat was just taken or this account is already in the room. Refresh and choose an open role.');
  await addRoomEvent(updated,user,role,`${user.name} joined as ${roleName(role)}.`);res.redirect(`/deal/${updated.code}`);
}catch(e){res.status(422).send(render('Unable to join room',`<h1>Unable to join room</h1><div class="notice">${escapeHtml(e.message)}</div><a class="button primary" href="/">Back to dashboard</a>`,req));}});
app.get('/deal/:code',signedIn,async(req,res)=>{const key=String(req.params.code||'').toUpperCase(),deal=await Deal.findOne({$or:[{code:key},{publicId:req.params.code}]});if(!deal)return res.status(404).send(render('Room not found','<h1>Room not found</h1><a href="/">Back to dashboard</a>',req));let role=roomRole(deal,req.session.user.id);if(!role&&req.session.user.role==='admin')role='admin';if(!role)return res.status(403).send(render('Room access required','<h1>Room access required</h1><p>Use the five-character code on your dashboard to join this room.</p><a class="button primary" href="/">Back to dashboard</a>',req));const messages=await RoomMessage.find({dealId:deal._id}).sort({createdAt:1}).limit(120).lean();return res.send(render(`Deal room ${deal.code||''}`,portal.room(deal,role,messages,res.locals.csrf,{escapeHtml,money,statusLabel:roomStatusLabel,roleLabel:roleName}),req));});
app.post('/room/:code/messages',signedIn,checkCsrf,async(req,res)=>{const deal=await Deal.findOne({code:String(req.params.code||'').toUpperCase()});const role=deal&&(roomRole(deal,req.session.user.id)||(req.session.user.role==='admin'?'admin':null)),body=String(req.body.body||'').trim();if(!deal||!role)return res.status(404).send('Room not found.');if(!body||body.length>2000)return res.status(422).send('Enter a message of 1 to 2,000 characters.');await RoomMessage.create({dealId:deal._id,userId:req.session.user.id,name:req.session.user.name,role,kind:'message',body});res.redirect(`/deal/${deal.code}#activity`);});
