app.post('/deals',signedIn,checkCsrf,async(req,res)=>{try{const title=String(req.body.title||'').trim(),terms=String(req.body.terms||'').trim(),sellerEmail=String(req.body.seller_email||'').trim().toLowerCase(),currency=String(req.body.currency||'KES');if(title.length<3||title.length>160||terms.length<10||terms.length>10000||!/^\S+@\S+\.\S+$/.test(sellerEmail))throw new Error('Please provide a valid title, seller email and delivery terms.');const amountMinor=amountFromForm(String(req.body.amount||''),currency),fee=feeMinor(currency,amountMinor),token=crypto.randomBytes(32).toString('hex');const deal=await Deal.create({publicId:crypto.randomBytes(13).toString('hex'),buyerId:req.session.user.id,sellerEmail,title,terms,currency,amountMinor,feeMinor:fee,inviteHash:crypto.createHash('sha256').update(token).digest('hex'),inviteExpires:new Date(Date.now()+7*86400000)});const link=`${process.env.APP_URL||'http://localhost:3000'}/invite?token=${token}`;await sendMail(sellerEmail,'Review a XWADDA.KE deal invitation',`${title}\nAgreed amount: ${money(currency,amountMinor)}\nBuyer fee: ${money(currency,fee)}\nReview terms: ${link}`);res.redirect('/my-deals');}catch(e){res.status(422).send(render('Deal not created',`<h1>Deal not created</h1><p>${escapeHtml(e.message)}</p><a href="/">Return to overview</a>`,req));}});
