app.get('/admin',signedIn,adminOnly,async(req,res)=>{const [deals,reports,users]=await Promise.all([Deal.find().sort({createdAt:-1}).limit(100).lean(),SafetyReport.find({status:'pending'}).sort({createdAt:1}).limit(100).lean(),User.find().sort({createdAt:-1}).limit(100).lean()]);const dealRows=deals.map(d=>`<article class="list"><b>${escapeHtml(d.title)}</b> · ${escapeHtml(d.status)} · ${money(d.currency,d.amountMinor)} + fee ${money(d.currency,d.feeMinor)}<p>Buyer ${escapeHtml(String(d.buyerId))} · Seller ${escapeHtml(d.sellerEmail)} · Ref ${escapeHtml(d.paymentRef||'none')}</p>${d.status==='payment_review'?`<form method="post" action="/admin/deal/${d.publicId}/confirm"><input type="hidden" name="csrf" value="${escapeHtml(res.locals.csrf)}"><label>Admin verification note<textarea name="note" required></textarea></label><button class="button button-primary">Confirm deposit verified</button></form>`:''}${['funded','delivered','disputed','release_requested'].includes(d.status)?`<form method="post" action="/admin/deal/${d.publicId}/resolve"><input type="hidden" name="csrf" value="${escapeHtml(res.locals.csrf)}"><select name="resolution"><option value="completed">Complete / manual payout approved</option><option value="refunded">Refund / cancellation approved</option></select><label>Admin note<textarea name="note" required></textarea></label><button class="button button-primary">Record decision</button></form>`:''}</article>`).join('');const reportRows=reports.map(r=>`<article class="list">${escapeHtml(r.category)} · ${escapeHtml(r.status)}<p>${escapeHtml(r.details)}</p><form method="post" action="/admin/report/${r._id}"><input type="hidden" name="csrf" value="${escapeHtml(res.locals.csrf)}"><button class="button button-primary">Mark reviewed</button></form></article>`).join('')||'<p>No pending safety reports.</p>';const userRows=users.map(u=>`<article class="list">${escapeHtml(u.name)} · ${escapeHtml(u.email)} · ${escapeHtml(u.role)} · ${escapeHtml(u.status)}<form method="post" action="/admin/user/${u._id}"><input type="hidden" name="csrf" value="${escapeHtml(res.locals.csrf)}"><select name="status"><option>active</option><option>suspended</option><option>closed</option></select><select name="role"><option>user</option><option>admin</option></select><button class="button button-primary">Update</button></form></article>`).join('');res.send(render('Admin panel',`<h1>Admin operations</h1><p>Manual verification and payout decision records are audited. Confirm receipt on the provider or chain before changing a payment to funded.</p><h2>Deals and payments</h2>${dealRows||'<p>No deals.</p>'}<h2>Safety reports</h2>${reportRows}<h2>Accounts</h2>${userRows}`,req));});
